const { withAppBuildGradle, withProjectBuildGradle } = require('expo/config-plugins');

// `apps/mobile/android/` is generated by `expo prebuild` and git-ignored, so the native settings
// that this project actually builds with live here instead of hand-edited Gradle files.
// See docs/CROSS_PLATFORM.md and docs/ANDROID_BUILD.md.
const MARKER = 'idukaa-native-build-settings';

const ROOT_BLOCK = `
// ${MARKER}: React Native 0.88 / Expo SDK 58 AARs enforce compileSdk 37 via their AAR metadata,
// and NDK 28.2 is the toolchain this project is built and verified with. Appended after Expo's
// own defaults so these values always win.
ext {
  compileSdkVersion = 37
  compileSdk = 37
  targetSdkVersion = 36
  targetSdk = 36
  buildToolsVersion = '36.1.0'
  ndkVersion = '28.2.13676358'
}
`;

const APP_BLOCK = `
    // ${MARKER}: Windows MAX_PATH (260) workaround. CMake mirrors node_modules source paths
    // under app/.cxx, which overflows the limit on Windows. Set IDUKAA_CXX_STAGING to a short
    // absolute path (e.g. "C:/x") for local Windows builds; other platforms are unaffected.
    if (System.getenv('IDUKAA_CXX_STAGING') != null) {
        externalNativeBuild {
            cmake {
                buildStagingDirectory System.getenv('IDUKAA_CXX_STAGING')
            }
        }
    }
`;

module.exports = function withAndroidBuildSettings(config) {
  config = withProjectBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(MARKER)) {
      cfg.modResults.contents += ROOT_BLOCK;
    }
    return cfg;
  });

  config = withAppBuildGradle(config, (cfg) => {
    const contents = cfg.modResults.contents;
    if (!contents.includes(MARKER)) {
      cfg.modResults.contents = contents.replace(/^android\s*\{/m, (match) => `${match}${APP_BLOCK}`);
    }
    return cfg;
  });

  return config;
};
